export type ParsedArgs = {
  positionals: string[]
  flags: Map<string, string[]>
}

export function parseArgs(argv: string[]): ParsedArgs {
  const flags = new Map<string, string[]>()
  const positionals: string[] = []

  for (let index = 0; index < argv.length; index += 1) {
    const current = argv[index] ?? ''
    if (!current.startsWith('--')) {
      positionals.push(current)
      continue
    }

    const trimmed = current.slice(2)
    const equalsIndex = trimmed.indexOf('=')
    if (equalsIndex >= 0) {
      const key = trimmed.slice(0, equalsIndex)
      const value = trimmed.slice(equalsIndex + 1)
      appendFlag(flags, key, value)
      continue
    }

    const next = argv[index + 1]
    if (!next || next.startsWith('--')) {
      appendFlag(flags, trimmed, 'true')
      continue
    }

    appendFlag(flags, trimmed, next)
    index += 1
  }

  return { positionals, flags }
}

function appendFlag(flags: Map<string, string[]>, key: string, value: string): void {
  const existing = flags.get(key) ?? []
  existing.push(value)
  flags.set(key, existing)
}

export function getFlagValue(parsed: ParsedArgs, key: string): string | undefined {
  return parsed.flags.get(key)?.at(-1)
}

export function getFlagValues(parsed: ParsedArgs, key: string): string[] {
  return parsed.flags.get(key) ?? []
}

export function hasFlag(parsed: ParsedArgs, key: string): boolean {
  return parsed.flags.has(key)
}
